<?= $this->include('layout/header') ?><form method="post"><label>Product</label><select name="product_id" required><option value="">Select product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>"><?= esc($p['name']) ?> — ₱<?= number_format($p['price'],2) ?> (stock: <?= $p['stock_quantity'] ?>)</option><?php endforeach ?></select><label>Customer (optional)</label><select name="customer_id"><option value="">Walk-in customer</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>"><?= esc($c['full_name']) ?></option><?php endforeach ?></select><label>Quantity</label><input type="number" name="quantity" min="1" required><button class="btn">Record Sale</button></form><?= $this->include('layout/footer') ?>
